//! Deterministic competing-mechanism exploration for Worldgen P08 F01-F04.
use std::collections::{BTreeMap,BTreeSet};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.mechanism-exploration-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct MechanismCandidate{pub mechanism_id:String,pub statement:String,pub support_milli:u32,pub novelty_milli:u32,pub evidence_state:String,pub evidence_digest:ContentHash,pub provenance_digest:ContentHash,pub artifact_digest:ContentHash,pub replay_identity:ContentHash,pub competing_order:Vec<String>,pub permitted:bool,pub raw_data_local:bool,pub negative_result:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct MechanismQuestion{pub request_id:String,pub question_id:String,pub purpose:String,pub semantic_profile:String,pub required_mechanism_order:Vec<String>,pub candidate_order:Vec<String>,pub candidates:Vec<MechanismCandidate>,pub replay_identity:ContentHash,pub min_support_milli:u32,pub policy_allow:bool,pub protected_closure:bool,pub federation_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct MechanismPortfolio{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub question_id:String,pub purpose:String,pub semantic_profile:String,pub disposition:String,pub required_mechanism_order:Vec<String>,pub candidate_order:Vec<String>,pub selected_order:Vec<String>,pub unresolved_order:Vec<String>,pub blocked_order:Vec<String>,pub omitted_order:Vec<String>,pub support_milli_order:Vec<u32>,pub novelty_milli_order:Vec<u32>,pub competing_order:Vec<String>,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub contradiction:Vec<String>,pub negative_evidence:Vec<String>,pub replay_identity:ContentHash,pub portfolio_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum MechanismExplorationError{#[error("invalid mechanism exploration request: {0}")]Invalid(String),#[error("mechanism exploration artifact failed: {0}")]Artifact(String),#[error("invalid mechanism portfolio: {0}")]Portfolio(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn s(v:Vec<String>)->Vec<String>{let mut o=v;o.sort();o.dedup();o}
impl MechanismPortfolio{pub fn validate(&self)->Result<(),MechanismExplorationError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.question_id.trim().is_empty()||self.purpose.trim().is_empty()||self.semantic_profile.trim().is_empty()||self.candidate_order.is_empty()||self.effect_receipts.is_empty()||![&self.replay_identity,&self.portfolio_digest].into_iter().all(h){return Err(MechanismExplorationError::Portfolio("mechanism identity, candidates, locality, digests, or effects are incomplete".into()));}for v in [&self.required_mechanism_order,&self.candidate_order,&self.selected_order,&self.unresolved_order,&self.blocked_order,&self.omitted_order,&self.competing_order,&self.omissions,&self.uncertainty,&self.contradiction,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(MechanismExplorationError::Portfolio("mechanism vectors are not canonical".into()));}}let ids=self.candidate_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.selected_order.iter().chain(&self.unresolved_order).chain(&self.blocked_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.candidate_order.len()||parts.len()!=ids.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=ids||self.support_milli_order.len()!=self.candidate_order.len()||self.novelty_milli_order.len()!=self.candidate_order.len(){return Err(MechanismExplorationError::Portfolio("mechanism states or score vectors do not partition".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.portfolio_digest.as_str()){return Err(MechanismExplorationError::Portfolio("mechanism artifact digest is inconsistent".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("explore:worldgen-mechanism:")){return Err(MechanismExplorationError::Portfolio("mechanism effect is outside exploration gate".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["imaging core scientist","research program lead","preclinical neuroscientist","bioinformatician"],"behavior":format!("rank competing preclinical mechanisms for {scale}"),"value":"preserves competing explanations, disagreement, uncertainty, provenance, and negative evidence instead of inventing a single mechanism","input_schema":input_schema,"output_schema":"MechanismPortfolio1@1","effects":["explore:worldgen-mechanism","block:unsafe-release"],"permissions":["explore:local-research-mechanism"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn explore(request:&MechanismQuestion,feature_id:&str,version:&str,scale:&str,require_federation:bool)->Result<MechanismPortfolio,MechanismExplorationError>{if request.request_id.trim().is_empty()||request.question_id.trim().is_empty()||request.purpose.trim().is_empty()||request.semantic_profile.trim().is_empty()||request.required_mechanism_order.is_empty()||request.candidate_order.is_empty()||request.candidate_order!=s(request.candidate_order.clone())||request.required_mechanism_order!=s(request.required_mechanism_order.clone())||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||request.min_support_milli>1000||!h(&request.replay_identity){return Err(MechanismExplorationError::Invalid("mechanism identity, ordering, threshold, locality, boundary, or replay is invalid".into()));}if require_federation&&!request.federation_approved{return Err(MechanismExplorationError::Invalid("mechanism federation approval is required".into()));}let ids=request.candidate_order.iter().cloned().collect::<BTreeSet<_>>();let mut by_id=BTreeMap::new();for c in &request.candidates{if !ids.contains(&c.mechanism_id)||c.boundary!=PRECLINICAL_BOUNDARY||!c.raw_data_local||c.replay_identity!=request.replay_identity||!h(&c.evidence_digest)||!h(&c.provenance_digest)||!h(&c.artifact_digest)||!h(&c.replay_identity){return Err(MechanismExplorationError::Invalid("mechanism candidate identity, provenance, locality, replay, or boundary is invalid".into()));}if by_id.insert(c.mechanism_id.clone(),c).is_some(){return Err(MechanismExplorationError::Invalid("duplicate mechanism candidate".into()));}}
let required=request.required_mechanism_order.iter().cloned().collect::<BTreeSet<_>>();let mut selected=Vec::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut omitted=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut contradiction=BTreeSet::new();let mut negative=BTreeSet::new();let mut competing=BTreeSet::new();for id in &ids{match by_id.get(id){None=>{omitted.insert(id.clone());omissions.insert(format!("mechanism:{}:missing",id));},Some(c)if !request.policy_allow||!request.protected_closure||!c.permitted=>{blocked.insert(id.clone());omissions.insert(format!("mechanism:{}:policy-or-permission-blocked",id));},Some(c)if c.negative_result=>{unresolved.insert(id.clone());negative.insert(format!("mechanism:{}:negative-result-retained",id));competing.extend(c.competing_order.iter().cloned());},Some(c)if c.evidence_state=="contradicted"=>{unresolved.insert(id.clone());contradiction.insert(format!("mechanism:{}:contradicted",id));competing.extend(c.competing_order.iter().cloned());},Some(c)if c.evidence_state=="unknown"||c.evidence_state=="unmeasured"=>{unresolved.insert(id.clone());uncertainty.insert(format!("mechanism:{}:{}",id,c.evidence_state));competing.extend(c.competing_order.iter().cloned());},Some(c)if c.support_milli<request.min_support_milli=>{unresolved.insert(id.clone());uncertainty.insert(format!("mechanism:{}:support-below-threshold",id));competing.extend(c.competing_order.iter().cloned());},Some(c)=>{selected.push(c);competing.extend(c.competing_order.iter().cloned());}}}selected.sort_by(|a,b|b.support_milli.cmp(&a.support_milli).then(b.novelty_milli.cmp(&a.novelty_milli)).then(a.mechanism_id.cmp(&b.mechanism_id)));let selected_ids=selected.iter().map(|c|c.mechanism_id.clone()).collect::<BTreeSet<_>>();let authority=request.policy_allow&&request.protected_closure&&(!require_federation||request.federation_approved);let disposition=if !authority{"blocked"}else if selected.is_empty(){"unknown"}else if selected_ids.len()==ids.len()&&omissions.is_empty()&&unresolved.is_empty()&&blocked.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("explore:worldgen-mechanism:{}",request.question_id)]};let support=request.candidate_order.iter().map(|id|by_id.get(id).map(|c|c.support_milli).unwrap_or(0)).collect::<Vec<_>>();let novelty=request.candidate_order.iter().map(|id|by_id.get(id).map(|c|c.novelty_milli).unwrap_or(0)).collect::<Vec<_>>();let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":request.request_id,"question_id":request.question_id,"purpose":request.purpose,"semantic_profile":request.semantic_profile,"scale":scale,"disposition":disposition,"required_mechanism_order":required,"candidate_order":ids,"selected_order":selected_ids,"unresolved_order":unresolved,"blocked_order":blocked,"omitted_order":omitted,"support_milli_order":support,"novelty_milli_order":novelty,"competing_order":competing,"omissions":omissions,"uncertainty":uncertainty,"contradiction":contradiction,"negative_evidence":negative,"replay_identity":request.replay_identity,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|MechanismExplorationError::Artifact(e.to_string()))?;let r=MechanismPortfolio{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:request.request_id.clone(),question_id:request.question_id.clone(),purpose:request.purpose.clone(),semantic_profile:request.semantic_profile.clone(),disposition:disposition.into(),required_mechanism_order:required.iter().cloned().collect(),candidate_order:ids.iter().cloned().collect(),selected_order:selected_ids.iter().cloned().collect(),unresolved_order:unresolved.iter().cloned().collect(),blocked_order:blocked.iter().cloned().collect(),omitted_order:omitted.iter().cloned().collect(),support_milli_order:support,novelty_milli_order:novelty,competing_order:competing.into_iter().collect(),omissions:omissions.into_iter().collect(),uncertainty:uncertainty.into_iter().collect(),contradiction:contradiction.into_iter().collect(),negative_evidence:negative.into_iter().collect(),replay_identity:request.replay_identity.clone(),portfolio_digest:d.clone(),effect_receipts:effects,artifact:json!({"artifact_id":format!("worldgen-mechanism-portfolio:{}",request.question_id),"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};r.validate()?;Ok(r)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn req()->MechanismQuestion{let r=h("replay");let c=MechanismCandidate{mechanism_id:"mech:a".into(),statement:"a".into(),support_milli:900,novelty_milli:700,evidence_state:"supported".into(),evidence_digest:h("e"),provenance_digest:h("p"),artifact_digest:h("a"),replay_identity:r.clone(),competing_order:vec!["mech:b".into()],permitted:true,raw_data_local:true,negative_result:false,boundary:PRECLINICAL_BOUNDARY.into()};MechanismQuestion{request_id:"req:a".into(),question_id:"q:a".into(),purpose:"explore".into(),semantic_profile:"profile".into(),required_mechanism_order:vec!["mech:a".into()],candidate_order:vec!["mech:a".into()],candidates:vec![c],replay_identity:r,min_support_milli:500,policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn supported_mechanism_is_ranked(){let r=explore(&req(),"AFA-worldgen-P08-F01","worldgen-local-mechanism/1.0","local single-study",false).unwrap();assert_eq!(r.disposition,"qualified");assert_eq!(r.selected_order,vec!["mech:a"]);assert!(r.competing_order.contains(&"mech:b".into()));}#[test]fn contradiction_is_preserved(){let mut q=req();q.candidates[0].evidence_state="contradicted".into();let r=explore(&q,"AFA-worldgen-P08-F02","worldgen-multimodal-mechanism/1.0","multimodal multi-study",false).unwrap();assert_eq!(r.disposition,"unknown");assert!(!r.contradiction.is_empty());}}
